       </div>

       <div className="p-4 bg-card rounded-lg border border-border">
         <div className="flex items-center justify-between mb-2">
           <div>
             <h3 className="text-lg font-semibold text-ink">{tierName} Plan</h3>
             <p className="text-sm text-muted-foreground">
-              {currentTier === 'STARTER' && 'Agencies getting started with access automation'}
-              {currentTier === 'GROWTH' && 'Agencies scaling their client operations'}
-              {currentTier === 'AGENCY' && 'High-volume agencies with advanced needs'}
+{currentTier === 'STARTER' && 'Agencies getting started with access automation'}
+               {currentTier === 'GROWTH' && 'Agencies scaling their client operations'}
+               {currentTier === 'SCALE' && 'High-volume agencies with advanced needs'}
               {!currentTier && 'Try before you commit'}
             </p>
           </div>
           <div className="text-right">
             <p className="text-2xl font-bold text-ink">
               {monthlyPrice}
             </p>
             <p className="text-sm text-muted-foreground">
               {!currentTier ? 'forever' : '/month'}
             </p>
           </div>
         </div>

         {subscription?.cancelAtPeriodEnd && (
           <div className="mt-3 p-2 bg-warning/10 border border-warning/30 rounded">
             <p className="text-sm text-warning">
               <AlertCircle className="h-4 w-4 inline mr-1" />
               Your subscription will cancel at the end of the current billing period.
             </p>
           </div>
         )}
       </div>

       <div className="flex items-center justify-between mt-4">
         <Button
           variant="ghost"
           onClick={handleManageSubscription}
           disabled={openPortal.isPending || !subscription}
         >
           {openPortal.isPending ? (
             <>
               <Loader2 className="h-4 w-4 animate-spin" />
               Opening...
             </>
           ) : (
             <>
               <ExternalLink className="h-4 w-4" />
               Manage in Billing Portal
             </>
           )}
         </Button>

         {subscription?.currentPeriodEnd && (
           <p className="text-sm text-muted-foreground">
             Next billing:{' '}
             {new Date(subscription.currentPeriodEnd).toLocaleDateString('en-US', {
               month: 'long',
               day: 'numeric',
               year: 'numeric',
             })}
           </p>
         )}
       </div>
     </section>
   );
 }

