   return hostname === 'localhost' || hostname === '127.0.0.1' || hostname === '::1';
 }

 function parseCsvList(value: string | undefined): string[] {
   if (!value) return [];
   return value
     .split(',')
     .map(item => item.trim())
     .filter(Boolean);
