         </div>

         {/* Upgrade Modal */}
         {showUpgradeModal && quotaError && (
           <UpgradeModal
             isOpen={showUpgradeModal}
             onClose={() => {
               setShowUpgradeModal(false);
               setQuotaError(null);
             }}
             quotaError={quotaError}
           />
         )}
       </div>
     </div>
   );
 }

