 function buildPlatformSummary(platforms: Platform[]): string {
   const uniqueNames = Array.from(new Set(platforms.map((platform) => PLATFORM_NAMES[platform])));

   if (uniqueNames.length <= 3) {
     return uniqueNames.join(', ');
