       <div className="flex items-center justify-center py-12">
         <Loader2 className="w-8 h-8 animate-spin text-danger-ink" />
       </div>
     );
   }

   const stepContent = renderStepContent();

   return (
     <PlatformWizardCard
       platform={platform}
       platformName={platformName}
       currentStep={currentStep}
       totalSteps={maxSteps}
       chrome="minimal"
     >
       {stepContent}
     </PlatformWizardCard>
   );
 }

