         const resolvedAgencyId = agencyLookup.data[0].id;
         const onboardingStatus = await authorizedApiFetch<{ data: AgencyOnboardingStatusData; error: null }>(
           `/api/agencies/${resolvedAgencyId}/onboarding-status`,
