         const resumeStep = resolveOnboardingResumeStep(onboardingStatus.data);
         setState((prev) => ({
           ...prev,
           agencyId: resolvedAgencyId,
           currentStep: prev.currentStep > 0 ? prev.currentStep : resumeStep,
         }));
       } catch {
