       }
     };

     void hydrateProgress();

     return () => {
       cancelled = true;
     };
   }, [enableProgressHydration, getToken, orgId, state.agencyId, state.currentStep, userId]);

   // ============================================================
   // ERROR HANDLING
   // ============================================================

   const setError = useCallback((error: string | null) => {
     setState((prev) => ({ ...prev, error }));
